"""Reduce pinned upstream report examples to check-level evidence, without running any scanner."""
from collections import Counter, defaultdict
import re
from xml.etree import ElementTree

from .product_reasoning import EvidenceError
from .product_review import sha
from .product_sources import git
from .repository_boundary import git_object
from .safe_io import canonical, strict_json

# These are reports generated by the named project, including its publication format.
# All upstream messages, code, paths, resource identifiers and locations stay in memory.
PROJECTS = {
    'kubescape/kubescape': ('076-kubescape', 'ef4faa945647cdd735f6aa3346567092f51c3a6a', 'kubescape-junit', {
        'core/pkg/resultshandling/printer/v2/testdata/junit_golden.xml': 'ad7cc1290401f8d0e4a0f0ab718aa3ccb471e1de'}),
    'aquasecurity/kube-bench': ('077-kube-bench', 'e278a5915a982f2756026de6e2f9ca77077ef9f9', 'kube-bench-json', {
        'cmd/testdata/result.json': '871483da282fe7f07251ab9c005a32d1f2151ce9'}),
    'phpstan/phpstan': ('106-phpstan', '043348b55e6c54effbdc0cd2f86173bc00ddd0c2', 'phpstan-playground', {
        'website/functional-tests/fixtures/277f76ee-e975-4b5a-87aa-5b4d0c2c2765.json': 'bbb9c1c83fa7ac35ee2c6d7138254b8878adb236',
        'website/functional-tests/fixtures/3cd4c73b-fd89-4bd1-9220-63ab82df2522.json': 'fa6663a5273b8248b41aeb83931c7740245b0267'}),
    'vimeo/psalm': ('107-psalm', '2da2040e23d8b54e61be22618bd53517b6bd43df', 'psalm-sarif', {
        'tests/sarif.json': '6bd0346715b98cad2f1ff98227d041a61f35640a'}),
}
BENCH_STATES = ('pass', 'fail', 'warn', 'info')
MAX_BYTES = 500_000


def require(condition, message):
    if not condition:
        raise EvidenceError(message)


def check_id(value, pattern):
    require(type(value) is str and re.fullmatch(pattern, value, re.ASCII), 'invalid report check identifier')
    return value


def summarize(checks):
    outcomes = Counter()
    rules = defaultdict(Counter)
    for check, state in checks:
        rules[check][state] += 1
        outcomes[state] += 1
    return {'itemized': sum(outcomes.values()), 'outcomes': dict(outcomes),
            'checks': {name: dict(counts) for name, counts in rules.items()}}


def parse_junit(raw):
    # Restrict this reader to plain UTF-8 JUnit without DTD, CDATA or declarations.
    content = raw.decode('utf-8')
    require('<!' not in content and '\x00' not in content, 'unsupported markup in JUnit report')
    try:
        return ElementTree.fromstring(content)
    except ElementTree.ParseError as error:
        raise EvidenceError('invalid JUnit document') from error


def junit_results(root):
    require(root.tag == 'testsuites' and root.attrib.get('name') == 'Kubescape Scanning', 'foreign JUnit producer')
    checks = []
    def totals(node, outcomes):
        for field, wanted in {'tests': sum(outcomes.values()), 'errors': outcomes['error'],
                              'failures': outcomes['fail'], 'skipped': outcomes['skipped']}.items():
            require(node.get(field) == str(wanted), 'JUnit summary differs from its test cases')

    suites = root.findall('testsuite')
    require(suites and len(suites) == len(root), 'unsupported JUnit suite nesting')
    for suite in suites:
        require(all(child.tag in ('properties', 'testcase') for child in suite), 'unsupported JUnit suite member')
        local = Counter()
        for case in suite.findall('testcase'):
            prefix, sep, identifier = case.attrib['classname'].rpartition('/')
            require(sep and prefix == suite.attrib['name'], 'JUnit control belongs to another suite')
            check = check_id(identifier, r'C-[0-9]{4,8}')
            markers = [child.tag for child in case]
            require(len(markers) <= 1 and all(t in ('failure', 'error', 'skipped') for t in markers),
                    'conflicting JUnit outcome')
            state = {'failure': 'fail', 'error': 'error', 'skipped': 'skipped'}[markers[0]] if markers else 'pass'
            local[state] += 1
            checks.append((check, state))
        totals(suite, local)
    summary = summarize(checks)
    totals(root, Counter(summary['outcomes']))
    return summary


def bench_totals(row):
    totals = {s: row['total_' + s] for s in BENCH_STATES}
    require(all(type(n) is int and n >= 0 for n in totals.values()), 'invalid kube-bench totals')
    return Counter(totals)


def bench_results(document):
    checks = []
    group_totals = Counter()
    for group in document['Controls']:
        group_details = Counter()
        for section in group['tests']:
            for item in section['results']:
                identifier = check_id(item['test_number'], r'[0-9]{1,3}(?:\.[0-9]{1,3}){1,5}')
                state = item['status']
                require(state in ('PASS', 'FAIL', 'WARN', 'INFO'), 'unknown kube-bench result')
                checks.append((identifier, state.lower()))
                group_details[state.lower()] += 1
        claimed = bench_totals(group)
        require(group_details <= claimed, 'kube-bench itemized count exceeds group summary')
        group_totals.update(claimed)
    require(group_totals == bench_totals(document['Totals']), 'kube-bench group and report totals disagree')
    summary = summarize(checks)
    # Native reports can omit the detail for part of the declared total.
    missing = group_totals - Counter(summary['outcomes'])
    summary.update(declared=sum(group_totals.values()), unitemized=dict(missing))
    return summary


def phpstan_results(document):
    checks = []
    for tab in document['result']['upToDateTabs']:
        for row in tab['errors']:
            require(type(row['line']) is int and row['line'] > 0, 'invalid PHPStan diagnostic location')
            identifier = check_id(row['identifier'], r'[a-zA-Z][a-zA-Z0-9]{0,63}\.[a-zA-Z][a-zA-Z0-9]{0,63}')
            checks.append((identifier, 'error'))
    return summarize(checks)


def psalm_results(document):
    require(document['version'] == '2.1.0', 'unsupported SARIF version')
    checks = []
    for run in document['runs']:
        driver = run['tool']['driver']
        require(driver['name'] == 'Psalm', 'foreign SARIF producer')
        rules = {check_id(r['id'], r'[A-Za-z][A-Za-z0-9]{0,95}'): r for r in driver['rules']}
        require(len(rules) == len(driver['rules']), 'duplicate SARIF rule identifier')
        for row in run['results']:
            identifier = row['ruleId']
            require(identifier in rules, 'SARIF result refers to an unknown rule')
            if 'ruleIndex' in row:
                i = row['ruleIndex']
                require(type(i) is int and 0 <= i < len(rules) and driver['rules'][i]['id'] == identifier,
                        'SARIF rule index differs from rule ID')
            config = rules[identifier].get('defaultConfiguration', {})
            level = row.get('level', config.get('level', 'warning'))
            require(level in ('none', 'note', 'warning', 'error'), 'unknown SARIF level')
            checks.append((identifier, level))
    return summarize(checks)


READERS = {'kubescape-junit': junit_results, 'kube-bench-json': bench_results,
           'phpstan-playground': phpstan_results, 'psalm-sarif': psalm_results}


def decode(format_name, raw):
    require(type(raw) is bytes and len(raw) <= MAX_BYTES, 'report input exceeds the byte limit')
    return parse_junit(raw) if format_name == 'kubescape-junit' else strict_json(raw)


def summary_with_controls(format_name, raw):
    """Test redaction invariance and a structural failure against these exact report bytes."""
    document = decode(format_name, raw)
    reader = READERS[format_name]
    summary = reader(document)
    require(summary['itemized'] > 0, 'upstream report has no itemized controls')
    sentinel = 'private-report-canary'
    if format_name == 'kubescape-junit':
        document.find('testsuite/testcase').set('name', sentinel)
        document.find('testsuite/testcase/failure').text = sentinel
    elif format_name == 'kube-bench-json':
        item = document['Controls'][0]['tests'][0]['results'][0]
        item.update(audit=sentinel, actual_value=sentinel, remediation=sentinel)
    elif format_name == 'phpstan-playground':
        document['result']['code'] = sentinel
        document['result']['tabs'] = []
        document['result']['upToDateTabs'][0]['errors'][0]['message'] = sentinel
    else:
        row = document['runs'][0]['results'][0]
        row.update(locations=[{'physicalLocation': {'artifactLocation': {'uri': sentinel}}}], message={'text': sentinel})
    require(reader(document) == summary, 'private fields affected the public summary')
    if format_name == 'kubescape-junit':
        document.set('failures', str(int(document.attrib['failures']) + 1))
    elif format_name == 'kube-bench-json':
        document['Totals']['total_pass'] += 1
    elif format_name == 'phpstan-playground':
        document['result']['upToDateTabs'][0]['errors'][0]['identifier'] = '../invalid'
    else:
        document['runs'][0]['results'][0]['ruleId'] = 'UnregisteredRule'
    try:
        reader(document)
    except EvidenceError:
        return summary
    raise EvidenceError('malformed upstream report was accepted')


def review(source_root):
    observations = {}
    for name, (directory, revision, format_name, fixtures) in PROJECTS.items():
        repo = source_root / directory
        require(not repo.is_symlink() and git(repo, 'rev-parse', 'HEAD').decode().strip() == revision,
                'report fixture checkout differs from the reviewed revision')
        output = {}
        for path, blob in fixtures.items():
            require(git(repo, 'ls-tree', '-z', revision, '--', path) == f'100644 blob {blob}\t{path}\0'.encode(),
                    'report fixture reference differs from its pinned path or blob')
            size = int(git(repo, 'cat-file', '-s', blob))
            require(0 < size <= MAX_BYTES, 'report fixture exceeds its bound')
            raw = git(repo, 'cat-file', 'blob', blob)
            require(size == len(raw) and git_object('blob', raw) == blob, 'report bytes differ from pinned source')
            output[path] = summary_with_controls(format_name, raw)
        observations[name] = {
            'revision': revision, 'role': 'reference', 'operation': 'summarize_pinned_report_without_resource_data',
            'source_manifest_sha256': sha(canonical(fixtures)), 'result': {'format': format_name,
                'summaries': output, 'private_field_substitution': 'invariant', 'malformed_control': 'rejected'}}
    from .product_report_quality_sources import observations as quality_observations
    observations.update(quality_observations(source_root))
    return observations
